/*
 * A121390  Sequence generated by the recurrence below begins with exactly
 *          seven primes.
 * https://oeis.org/A121390
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0)=2; a(1)=8607769; a(n)=a(n-2)*a(n-1)+a(n-2)+a(n-1)
 * Range:     u8 n <= 0, u16 n <= 0, u32 n <= 2, u64 n <= 3, u128 n <= 5,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;          /* array of computed terms      */
    static size_t cap   = 0;             /* current array capacity      */
    static idx_t  last  = 0;             /* last index that has been    */
                                         /* computed (0‑based)           */

    /* first call: initialise cache with a(0) and a(1)           */
    if (cache == NULL) {
        cap   = 2;                       /* need room for indices 0 and1*/
        cache = (seq_t*)malloc(cap * sizeof(seq_t));
        if (cache == NULL) {             /* allocation failed            */
            return (seq_t)0;
        }
        cache[0] = (seq_t)2;
        cache[1] = (seq_t)8607769;
        last     = 1;                    /* a(1) has been computed      */
    }

    /* if requested index already computed, return it           */
    if (n <= last) {
        return cache[(size_t)n];
    }

    /* grow cache to accommodate the requested index            */
    if ((size_t)n >= cap) {
        size_t new_cap = cap * 2;
        if (new_cap <= (size_t)n) {
            new_cap = (size_t)n + 1;
        }
        seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (tmp == NULL) {               /* reallocation failed        */
            return (seq_t)0;
        }
        cache = tmp;
        cap   = new_cap;
    }

    /* compute missing terms up to n                            */
    for (idx_t k = last + 1; k <= n; ++k) {
        seq_t a1 = cache[(size_t)(k - 1)];
        seq_t a2 = cache[(size_t)(k - 2)];
        cache[(size_t)k] = a1 * a2 + a1 + a2;
    }
    last = n;

    return cache[(size_t)n];
}
